questionvariables.text:
/* ================================================================== ZONE DE CONFIGURATION ENSEIGNANT (a editer uniquement ici) STACK n'offre pas de panneau JSON dedie : ces trois lignes sont l'equivalent editable sans toucher au reste du code Maxima. smiles_dessin : chaine SMILES de la molecule imposee nom_attendu : nom IUPAC exact attendu de l'eleve famille_attendue : famille chimique (affichee en feedback) ================================================================== */ smiles_dessin : "CC(C)CC(C)(C)C"$ nom_attendu : "2,2,4-triméthylpentane"$ famille_attendue : "Alcanes"$ /* ================================================================== */
molecule_smiles : smiles_dessin$ famille : famille_attendue$ nom : nom_attendu$
molecule_smiles_url : molecule_smiles$ molecule_smiles_url : ssubst("%5C", "\\", molecule_smiles_url)$ molecule_smiles_url : ssubst("%2F", "/", molecule_smiles_url)$ molecule_smiles_url : ssubst("%28", "(", molecule_smiles_url)$ molecule_smiles_url : ssubst("%29", ")", molecule_smiles_url)$ molecule_smiles_url : ssubst("%3D", "=", molecule_smiles_url)$
/* Construction d'un pattern RegExp tolerant (casse, tirets/espaces interchangeables) en un seul passage caractere par caractere, pour eviter toute collision de substitutions successives. */ regexify_nom(s) := block([chars, out, c], chars : charlist(s), out : "(?i)^", for c in chars do ( out : if c = "(" then sconcat(out, "\\(") elseif c = ")" then sconcat(out, "\\)") elseif c = "-" then sconcat(out, "[- ]?") elseif c = " " then sconcat(out, "[- ]?") else sconcat(out, c) ), out : sconcat(out, "$"), out)$
nom_pattern : regexify_nom(nom_attendu)$
